 {modal.kind==='deleteProduct'&&<><p className="eyebrow">INVENTARIO</p><h2>{modal.saved?'Producto eliminado':'¿Estás seguro de eliminar este producto?'}</h2><div className="delete-product-summary"><b>{productLabel(modal.p)}</b><small>Código: {modal.p.code}</small><small>Stock: {modal.p.stock} unidades</small></div><p className="muted">Se retirará del inventario y de las nuevas ventas. Las ventas y comprobantes anteriores se conservarán. Para cancelar, cierra con la X.</p><button className="danger-button full" disabled={busy||modal.saved} onClick={()=>save({action:'deleteProduct',id:modal.p.id,confirmed:true,expectedStock:modal.p.stock})}><Trash2 size={16}/>{busy?'Eliminando…':modal.saved?'Eliminado':'Sí, eliminar producto'}</button></>}
 {modal.kind==='settings'&&<><p className="eyebrow">CONFIGURACIÓN</p><h2>Ajustes de la empresa</h2><form onSubmit={e=>{e.preventDefault();if(!uploading)save({action:'settings',...modal.settings,...Object.fromEntries(new FormData(e.currentTarget))})}}><label>Nombre del local<input autoFocus required maxLength={80} value={modal.settings.name} onChange={e=>M({...modal,saved:false,settings:{...modal.settings,name:e.target.value}})}/></label><label>Nombre del representante<input name="representative" maxLength={160} defaultValue={modal.settings.representative}/></label><div className="formrow"><label>RUT de empresa<input name="rut" maxLength={20} defaultValue={modal.settings.rut}/></label><label>Teléfono<input name="phone" type="tel" maxLength={30} defaultValue={modal.settings.phone}/></label></div><label>Dirección<input name="address" maxLength={160} defaultValue={modal.settings.address}/></label><div className="formrow"><label>Ancho de comprobante<select name="receiptWidth" defaultValue={business.receiptWidth||'80'}><option value="80">80 mm</option><option value="58">58 mm</option></select></label><label>Mensaje de despedida<input name="receiptFooter" maxLength={160} defaultValue={business.receiptFooter}/></label></div><div className="photo-upload">{modal.settings.logo?<img src={modal.settings.logo} alt="Logo de la empresa"/>:<Store size={32}/>}<div><label className="photo-label">Logo de la empresa<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy||uploading} onChange={e=>{M({...modal,saved:false});uploadPhoto(e.target.files?.[0],'logo');e.target.value=''}}/></label><small>{uploading?'Subiendo logo…':'JPG, PNG o WebP · Máximo 5 MB'}</small>{modal.settings.logo&&<button type="button" className="textbtn" disabled={busy||uploading} onClick={()=>M({...modal,saved:false,settings:{...modal.settings,logo:''}})}>Quitar logo</button>}</div></div><div className="company-preview"><small>VISTA PREVIA DEL COMPROBANTE</small><CompanyHeader business={modal.settings}/></div><button className="primary full" disabled={busy||uploading||modal.saved}>{uploading?'Subiendo logo…':busy?'Guardando…':'Guardar ajustes'}</button></form></>}
 {modal.kind==='supplier'&&<SupplierForm supplier={modal.supplier} save={save} busy={busy}/>}
